with flattened_attrs as (select id, plan, effective_from, currency, tier_prices, discounts, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, array_min(tier_prices) as lowest_price from price_tiers where currency in ('USD', 'EUR')) select plan, sum(case when currency = 'EUR' then lowest_price else 0 end) as eur_lowest_price, approx_percentile(lowest_price, array(0.25, 0.5, 0.75)) as lowest_price_quartiles, count(*) filter (where currency = 'EUR') as eur_rows from flattened_attrs group by rollup (plan);
